"""Aula 32 · Real-Life Mission Day 4 (A1, 60 min). Gera data/v3/032.json."""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
from rl_common import PLAN, teach, finish

UNIT_MAP = ['Taking the bus or subway', 'At the train station', 'Checking in at the airport', 'Taking a taxi or rideshare', 'Renting a bike or a car', 'When you are lost', 'Hotel check-in', 'Real-Life Mission Day 4']
UNIT = lambda k: dict(n=4, k=k, of=8, name='Getting around')
CRIT = [dict(k='flu', name='Fluency', desc='Mantém a comunicação sem interrupções excessivas.'), dict(k='lan', name='Language use', desc='Utiliza adequadamente padrões, vocabulário e expressões.'), dict(k='pro', name='Pronunciation', desc='É compreensível e usa ritmo e entonação adequados.'), dict(k='int', name='Interaction', desc='Responde, pergunta, esclarece e desenvolve a conversa.')]
INTERP = [dict(max=8, text='Needs more support. Revisit the main patterns with guided practice before the next lesson.'), dict(max=13, text='Functional performance. Work on the lowest criteria in the next lesson.'), dict(max=17, text='Good control. Raise complexity and speed; add follow-up questions.'), dict(max=20, text='Strong performance. Move to a more demanding situation.')]
LEVELS_NOTE = 'This progression is illustrative: complex sentences do not define a level on their own. CEFR also considers comprehension, autonomy, fluency, accuracy, interaction and appropriateness.'


def build(c):
    k = c['k']; n = 24 + k
    a, b = c['cast']
    sp = {c['roles'][0]: {'name': a}, c['roles'][1]: {'name': b}}
    E = c['errs']; X = c['extra']
    sup = lambda s: [s]
    ch = c['chunks']; pri = [x['en'] for x in ch if x.get('pri')]
    P = []
    P.append(dict(t='rl_open', stage='warm', title=c['title'], pt=c['pt'], level='A1', unit=dict(UNIT(k), map=UNIT_MAP), situation=dict(text=c['sit'], scene=c['scene'], tod=c.get('tod', 'day'), cast=[a, b]), goal=c['goal'], canDo=c['canDo'], success=c['success'], think=c['think'],
     teach=teach(goal='Abrir a aula pela situação real, não pela regra.', solo=['Leia o objetivo em voz alta e peça que o estudante diga com as próprias palavras o que vai fazer hoje.', 'Pergunte “Think about it” antes de mostrar qualquer expressão.'], group=['Cada estudante diz UMA palavra que associa à situação de hoje.', 'Mostre os 4 critérios de sucesso: é a missão final da aula.'], extra=X[0:2], support=['Aceite respostas curtas ou em português na primeira rodada e reformule em inglês.'])))
    P.append(dict(t='rl_warm', stage='warm', title='Connection & warm-up', intro=dict(solo='Start with real questions about the student’s life, not a grammar test.', group='One question per student, then a question back to a classmate.'), recall=c['recall'], qs=c['warm'], tip='Use the answers to find gaps and to recycle earlier content. The goal is to enter English from the first minute.',
     teach=teach(goal='Entrar no idioma no primeiro minuto, retomar a aula anterior e mapear lacunas.', extra=X[2:4], errors=[dict(w='I have 25 years.', r='I’m 25.'), dict(w='I go to work by foot.', r='I walk to work.')], support=['Ofereça as respostas-modelo (chips) e peça apenas que escolham uma.'])))
    cu = c['culture']
    P.append(dict(t='rl_culture', stage='immersion', title='Cultural snapshot — ' + cu['head'], intro=cu['intro'], cards=cu['cards'], qs=cu['qs'], compare=cu['compare'],
     teach=teach(goal='Ativar o contexto cultural e as primeiras hipóteses.', solo=['Mostre os 3 cartões e peça hipóteses antes de explicar.', 'Peça que o estudante compare com a sua própria experiência no Brasil.'], group=['Cada estudante escolhe um cartão e explica em uma frase.', 'Pergunte “Do you agree?” entre colegas.'], answers=cu['answers'], extra=X[4:5], support=['Use as respostas do nível A1 como andaime e peça que repitam.'], stretch=['B2: compare as convenções do Brasil e dos EUA nesta situação.'])))
    li = c['listen']
    P.append(dict(t='rl_listen', stage='immersion', title='Scene & listening', scene=dict(scene=c['scene'], tod=c.get('tod', 'day'), cast=[a, b]), pass1=li['pass1'], pass2=dict(tasks=li['tasks']),
     teach=teach(goal='Compreender a situação antes de ver o texto: ideia principal e depois as informações-chave.', solo=['Esconda o texto. 1ª escuta: só a ideia principal.', '2ª escuta: as informações da tarefa 2.', 'Mostre o texto só depois da 2ª escuta.'], group=['Escuta coletiva; duplas anotam as respostas antes de revelar.', 'Compare as respostas entre as duplas e só então mostre o texto.'], answers=li['answers'], extra=['Who is speaking? How do you know?', 'Which word did you catch first?'], support=['Use o botão “Slow” na 2ª escuta.', 'Pause depois de cada fala se necessário.'])))
    dg = c['dq']
    P.append(dict(t='rl_dialog', stage='notice', title='Dialogue — a real-life conversation', qs=dg['qs'], retell=dict(prompt='Retell the conversation in your own words, at your level.', starters=dg['starters']),
     teach=teach(goal='Ler o diálogo, perceber os chunks e recontar.', solo=['O estudante lê um papel e você lê o outro; depois trocam.', 'Peça que reconte a conversa no nível que conseguir.'], group=['Leitura em duplas e troca de papéis.', 'Reconto em cadeia: uma frase por estudante.'], answers=dg['answers'], extra=X[5:6], errors=E[0:2], support=['Mostre a tradução (botão PT) depois da 2ª leitura.'])))
    P.append(dict(t='rl_chunks', stage='notice', title='Useful expressions', items=ch, discover=c['discover'], note='Instead of memorizing the whole list, choose 3–5 expressions (★) to use again and again. The others are for understanding and for stretching later.',
     teach=teach(goal='Escolher 3–5 chunks para uso repetido e descobrir a função de cada um.', solo=['Pergunte “When do you say it?” antes de dar o significado.', 'Peça um exemplo próprio para cada expressão ★.'], group=['Cada estudante escolhe a expressão que mais usaria e explica quando.', 'Compare equivalentes formais e informais em duplas.'], answers=['Prioritárias: ' + ' · '.join(pri)], extra=X[6:7], errors=E[2:3], support=['Trabalhe só as expressões ★ nesta aula.'])))
    P.append(dict(t='rl_patterns', stage='gram', title='Grammar in context — speaking patterns', patterns=c['patterns'], swap=c['swap'], register=c['register'],
     teach=teach(goal='Fixar os padrões principais; os outros são expansão. Usar a troca de palavras para variar a fala.', solo=['Mostre o padrão DENTRO do diálogo (grife os chunks).', 'Use “Swap the words”: toque em cada peça e peça que o estudante diga a frase completa.', 'Compare spoken × written em 2 exemplos.'], group=['Troca em cadeia: cada estudante muda UMA peça e o próximo repete a frase.', 'Em pares: um escolhe as peças, o outro fala.'], answers='Os padrões principais (main) são o foco; os demais são expansão para quem avançar rápido.', extra=X[7:8], errors=E[3:6], support=['Fique só com o primeiro padrão na primeira rodada.'], stretch=['Combinar dois padrões na mesma fala.'])))
    pr = c['pron']
    P.append(dict(t='rl_pron', stage='gram', title='Pronunciation lab — natural American English', focus=pr['focus'], tip=pr['tip'], items=pr['items'], identify=pr['identify'], own=pr['own'],
     teach=teach(goal='UM só fenômeno: ' + pr['focus'] + '.', solo=['3 passagens: escutar e identificar → reproduzir ritmo e entonação → usar em frase com conteúdo próprio.', 'Modele devagar e normal; peça que o estudante bata palmas na sílaba forte.'], group=['Coro, depois duplas; circule ouvindo.', 'Cada estudante cria uma frase própria.'], answers=pr['answers'], errors=pr['errs'], support=['Reduza a velocidade e conte as batidas em voz alta.'])))
    P.append(dict(t='rl_challenge', stage=dict(solo='practice', group='gram'), title='Guided challenges', levels=[dict(h='Controlled practice — choose the best answer', items=c['ch1']), dict(h='Guided practice — complete, substitute and transform', items=c['ch2'])],
     teach=teach(goal='Do controlado ao guiado: completar, substituir e transformar antes da fala livre.', solo=['Peça que o estudante justifique cada resposta.', 'Se acertar rápido, peça a versão mais informal ou mais educada.'], group=['Resolvam em duplas e comparem antes de revelar.', 'Equipes: ponto por resposta justificada.'], answers=c['ch_answers'], extra=X[8:9], errors=E[6:7], support=['Ofereça o banco de palavras (chips) nas lacunas.'])))
    ro = c['role']
    P.append(dict(t='rl_role', for_='solo', stage='speak1', title='Personalized roleplay — ' + ro['title'], brief=ro['brief'], orders=ro['orders'], complications=ro['complications'],
     rounds=[dict(label='With support', desc='Chunks on screen', help=pri), dict(label='Keywords', desc='Only the keywords', help=ro['kw'], kw=True), dict(label='No script', desc='Free', help=[])], success=c['success'],
     teach=teach(goal='Simulação com complicação inesperada e três rodadas com menos apoio.', solo=['Combine o cenário com a vida do estudante (um lugar que ele realmente frequenta).', 'Rodada 1: com chunks. Rodada 2: só palavras-chave. Rodada 3: sem roteiro.', 'Meta de fala: 60–70% do tempo para o estudante. Anote 2–3 correções para a devolutiva.'], extra=X[9:10], errors=E[0:1], support=['Volte à rodada 1 se travar; peça que repita só a primeira frase.'], stretch=ro['stretch'])))
    lb = c['lab']
    P.append(dict(t='rl_lab', for_='group', stage='speak1', title='Communication lab — conversation rotations', rounds=lb['rounds'], infogap=lb['infogap'],
     teach=teach(goal='Fluência por repetição da função com informações novas a cada rodada.', group=['Troque os pares a cada rodada (A+B / C+D → A+C / B+D → A+D / B+C → grupo todo). Com 6 estudantes, três duplas simultâneas.', 'Sem salas simultâneas: interações sequenciais enquanto uma dupla apresenta.', 'Responsabilidade individual: cada aluno faz ≥1 pergunta e ≥1 resposta.'], answers=lb['answers'], extra=lb['extra'], errors=lb['errs'], support=['Entregue frases-modelo no chat da turma.'])))
    P.append(dict(t='rl_mission', for_='group', stage='speak2', title='Group mission — ' + c['mtitle'], goal=c['mgoal'], missions=c['missions'], min=11, success=c['msuccess'],
     teach=teach(goal='Realizar algo com o inglês: o objetivo é resolver, não só falar certo.', group=['Cada grupo recebe papel, restrição e missão. Alterne os papéis.', 'Progressão: 1ª rodada com frases de apoio, 2ª só palavras-chave, 3ª sem roteiro.', 'Observe e anote 2–3 correções prioritárias; devolutiva no fim.'], answers=c['manswer'], extra=['What if the other person does not understand you?'], support=['Dê o início de frase (“Start with”) em cada cartão.'])))
    w = c['write']
    P.append(dict(t='rl_write', stage='write', title='Writing — a small real-life task', task=w['task'], steps=w['steps'], model=w['model'], checklist=w['checklist'], tip='Fix only 2–3 priority points. Show a more natural way to say the same idea instead of rewriting everything.', fix=dict(n=3),
     teach=teach(goal='Produção escrita curta ligada à situação comunicativa.', solo=['Peça o texto; corrija 2–3 pontos prioritários e mostre uma forma mais natural.'], group=['Cada estudante escreve; depois troquem os textos entre colegas e corrijam em duplas.'], extra=X[10:11] if len(X) > 10 else ['Add one more detail to your text.'], errors=E[7:8] if len(E) > 7 else E[0:1], support=['Dê o modelo e peça só para trocar os dados.'])))
    P.append(dict(t='rl_feedback', stage='write', title='Feedback & review — Speaking Performance Check', criteria=CRIT, interpret=INTERP, prompts=c['prompts'],
     teach=teach(goal='Avaliar o que o aluno conseguiu comunicar, não só os erros gramaticais.', solo=['O estudante se autoavalia primeiro; depois você.', 'Feche com os três blocos: What you did well · What to improve · Your next challenge.'], group=['Dê um comentário por critério a cada estudante.', 'Cada um escolhe o próprio próximo desafio.'], answers='A rubrica é uma ferramenta interna de acompanhamento, não uma certificação CEFR.')))
    ex = c['exit']
    P.append(dict(t='rl_exit', stage='exit', title='Exit ticket & homework', tasks=ex['tasks'], homework=dict(h='Your real-life English mission', min='10–15', items=ex['hw']), spaced=ex['spaced'],
     teach=teach(goal='Toda aula termina com uma produção observável.', solo=['Sem consultar as anotações: construir uma pergunta, responder a uma situação e usar uma expressão nova.'], group=['Exit challenge individual; compare com o colega e combine a tarefa de continuidade.'], answers=' · '.join(t['model'] for t in ex['tasks']), extra=['Revisão espaçada: retomar na próxima aula, depois de uma semana e na missão de encerramento da unidade.'])))
    P.append(dict(t='rl_levels', stage='exit', title='Level up — the same situation from A1 to C2', you='A1', intro='You do not need six different methods: the structure stays, while language complexity and autonomy grow.', ladder=[dict(lv=l, say=s, goal=g) for l, s, g in c['ladder']], note=LEVELS_NOTE,
     teach=teach(goal='Mostrar a progressão sem criar seis metodologias.', solo=['Mostre onde o estudante está e a próxima etapa.'], group=['Cada um escolhe a frase do próprio nível e a do próximo.'])))
    return dict(n=n, topic=c['title'], level='A1', title=c['title'], pt=c['pt'], unit=UNIT(k), minutes=60, cast=[a, b], scene=c['scene'], tod=c.get('tod', 'day'), plan=PLAN, dialog=dict(speakers=sp, lines=c['lines']), pages=P)

def Q(q, pt, sup): return dict(q=q, pt=pt, sup=sup)
def LV(a1, a2, b1, b2): return dict(A1=a1, A2=a2, B1=b1, B2=b2)
def L(who, en, pt): return dict(who=who, en=en, pt=pt)
def O(en, pt): return dict(en=en, pt=pt)

